import React, { useState, useEffect } from 'react';
import ActivityTimeline from './ActivityTimeline';

const TestTimeline = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch the CSV file
        const response = await fetch('/focus_logs/2025-04-27/activity_log.csv');
        const text = await response.text();

        // Parse CSV
        const rows = text.split('\n');
        const headers = rows[0].split(',');

        const parsedData = rows.slice(1)
          .filter(row => row.trim())
          .map(row => {
            const values = row.split(',');
            const obj = {};
            headers.forEach((header, index) => {
              if (header === 'timestamp') {
                obj[header] = values[index];
              } else if (['active', 'elapsed_time', 'work_elapsed', 'leisure_elapsed'].includes(header)) {
                obj[header] = parseFloat(values[index]);
              } else {
                obj[header] = values[index];
              }
            });
            return obj;
          });

        setData(parsedData);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching data:', err);
        setError('Failed to load activity data');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;
  if (!data) return <div>No data available</div>;

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">Activity Timeline Test</h1>
      <div className="bg-white p-4 rounded shadow">
        <ActivityTimeline data={data} />
      </div>

      {/* Display statistics */}
      <div className="mt-4 grid grid-cols-4 gap-4">
        {['work', 'leisure', 'break', 'inactive'].map(mode => {
          const modeIntervals = data.filter(row => 
            (mode === 'work' && row.active === 1) ||
            (mode === 'leisure' && row.active === 2) ||
            (mode === 'break' && row.active === 0)
          );

          const totalMinutes = modeIntervals.reduce((acc, row) => {
            return acc + (row.elapsed_time ? row.elapsed_time / 60 : 0);
          }, 0);

          return (
            <div key={mode} className="bg-white p-4 rounded shadow">
              <h3 className="text-lg font-semibold capitalize">{mode}</h3>
              <p>{(totalMinutes / 60).toFixed(2)} hours</p>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default TestTimeline;
